/** Curated services plus the generated directory, for dashboard search. */
export const ALL_SERVICES: CampusService[] = [...CAMPUS_SERVICES, ...DIRECTORY_SERVICES];

export function findServiceBySlug(slug: string | null | undefined): CampusService | undefined {
  return slug ? ALL_SERVICES.find(service => service.slug === slug) : undefined;
}
